plugins {
    id("java")
    id("jacoco")
    id("application")
    id("com.diffplug.spotless") version "7.2.1"
    id("info.solidsoft.pitest") version "1.19.0-rc.1"
    id("org.springframework.boot") version "3.4.5"
    id("io.spring.dependency-management") version "1.1.7"
}

